-- 042_public_random_paper: explicit opt-in public pools; historical releases remain category scoped.
-- Replace full prior probes without editing applied migrations or checksums.

-- @step paper_pool_scope
-- @replaces-check 032_paper_operation_metadata/paper_updated_by
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper') = 25 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper' AND ((COLUMN_NAME = 'regulation_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'business_scope' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'regulation') OR (COLUMN_NAME = 'mode' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'fixed') OR (COLUMN_NAME = 'category_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'requires_learning' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '1') OR (COLUMN_NAME IN ('regulation_ids', 'course_ids', 'rule_config') AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL))) = 8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper' AND INDEX_NAME = 'idx_paper_training_pool' AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'business_scope') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'mode') OR (SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'status')) AND NON_UNIQUE = 1 AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='designer_layout' AND DATA_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND ((COLUMN_NAME='required_learning_minutes' AND DATA_TYPE='int' AND COLUMN_TYPE='int unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='') OR (COLUMN_NAME='remark' AND DATA_TYPE='varchar' AND COLUMN_TYPE='varchar(1000)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')))=2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='course_ids' AND COLUMN_COMMENT='考前学习课程关联，不参与抽题过滤')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='sort_order' AND DATA_TYPE='int' AND COLUMN_TYPE='int' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='0' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='updated_by' AND DATA_TYPE='bigint' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='pool_scope' AND COLUMN_TYPE='varchar(16)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='category' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE exam_paper ADD COLUMN pool_scope VARCHAR(16) NOT NULL DEFAULT 'category' AFTER mode;

-- @step release_pool_scope
-- @replaces-check 030_paper_learning_requirement/release_learning_requirement
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release') = 14 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('paper_id', 'created_by') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'version_no' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('business_scope', 'mode') AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'category_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'requires_learning' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'rule_snapshot' AND DATA_TYPE = 'json' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('regulation_ids', 'course_ids') AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'released_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED'))) = 12 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id') OR (INDEX_NAME = 'uk_paper_release_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'paper_id') OR (INDEX_NAME = 'uk_paper_release_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'version_no') OR (INDEX_NAME = 'idx_paper_release_category' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='paper_release' AND COLUMN_NAME='required_learning_minutes' AND DATA_TYPE='int' AND COLUMN_TYPE='int unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='paper_release' AND COLUMN_NAME='pool_scope' AND COLUMN_TYPE='varchar(16)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='category' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE paper_release ADD COLUMN pool_scope VARCHAR(16) NOT NULL DEFAULT 'category' AFTER mode;

-- Preserve 041's final status contract when validating the retired 040 probe.
-- @step retain_withdraw_to_draft_status
-- @replaces-check 040_paper_withdraw_metadata/describe_paper_withdrawn_status
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='status' AND COLUMN_TYPE='varchar(16)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='draft' AND COLUMN_COMMENT='draft / published；withdrawn / archived 仅历史兼容') THEN 1 ELSE 0 END AS complete;
ALTER TABLE exam_paper MODIFY COLUMN status VARCHAR(16) NOT NULL DEFAULT 'draft' COMMENT 'draft / published；withdrawn / archived 仅历史兼容';
